package network

import (
	"math"
	"slices"
	"time"

	"github.com/burntcustard/unicorn-mining-co/src/server/protocol"
	"github.com/burntcustard/unicorn-mining-co/src/server/specs"
)

func (s *GameSession) sectorMapView(player *playerRecord, position specs.Vector) {
	now := s.now()

	if player.socket == nil || (!player.mapAt.IsZero() && now.Sub(player.mapAt) < 200*time.Millisecond) || math.Abs(position.X) > 1e9 || math.Abs(position.Y) > 1e9 {
		return
	}

	player.mapAt = now
	// Static fields are generated by the client. All finite sector landmarks
	// and connected players are sent together so panning needs no round trip.
	markers := slices.Clone(s.regions.Procedural.MapStations())

	for _, portal := range s.sectors[s.currentSector].portals {
		markers = append(markers, protocol.MapMarker{Kind: portal.Kind, ID: portal.ID, Position: portal.Position, Name: portal.Name})
	}

	s.sectorPlayers(func(p *playerRecord, _ string) {
		if !s.World.Players.Has(p.playerID) || p.ship.Dead {
			return
		}

		markers = append(markers, protocol.MapMarker{Kind: "ship", ID: p.shipID, Position: p.ship.Position, Name: p.profile.DisplayName, Color: p.ship.Shades[2]})
	})

	s.sendControl(player.socket, protocol.ServerControl{Type: "sectorMap", MapMarkers: markers})
}
